import { basename, posix } from "node:path";

export function isGeneratedLockfile(path) {
  const name = basename(path);
  return name === "Cargo.lock" || name === "package-lock.json";
}

export function isDeterministicBinaryAsset(path) {
  const name = basename(path).toLowerCase();
  return name.endsWith(".png") || name.endsWith(".ico") || name.endsWith(".icns");
}

export function siblingPackageJsonPath(path) {
  return posix.join(posix.dirname(path), "package.json");
}

export function validateBinaryAsset({ path, content }) {
  const name = basename(path).toLowerCase();
  const bytes = Buffer.from(content);

  if (name.endsWith(".png")) {
    if (bytes.length < 24) {
      throw new Error(`PNG asset is too small: ${path}`);
    }
    const signature = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
    if (!bytes.subarray(0, 8).equals(signature) || bytes.subarray(12, 16).toString("ascii") !== "IHDR") {
      throw new Error(`invalid PNG structure: ${path}`);
    }
    const width = bytes.readUInt32BE(16);
    const height = bytes.readUInt32BE(20);
    if (width === 0 || height === 0 || width > 8192 || height > 8192) {
      throw new Error(`invalid PNG dimensions in ${path}`);
    }
    return { kind: "png", bytes: bytes.length, width, height };
  }

  if (name.endsWith(".ico")) {
    if (bytes.length < 6 || bytes.readUInt16LE(0) !== 0 || bytes.readUInt16LE(2) !== 1) {
      throw new Error(`invalid ICO header: ${path}`);
    }
    const imageCount = bytes.readUInt16LE(4);
    if (imageCount === 0) {
      throw new Error(`ICO contains no images: ${path}`);
    }
    return { kind: "ico", bytes: bytes.length, image_count: imageCount };
  }

  if (name.endsWith(".icns")) {
    if (bytes.length < 8 || bytes.subarray(0, 4).toString("ascii") !== "icns") {
      throw new Error(`invalid ICNS header: ${path}`);
    }
    const declaredLength = bytes.readUInt32BE(4);
    if (declaredLength !== bytes.length) {
      throw new Error(`ICNS length mismatch in ${path}`);
    }
    return { kind: "icns", bytes: bytes.length };
  }

  throw new Error(`unsupported binary asset: ${path}`);
}

function sortedEntries(value = {}) {
  return Object.entries(value).sort(([left], [right]) => left.localeCompare(right));
}

function assertSameObject(label, expected = {}, actual = {}) {
  const left = JSON.stringify(sortedEntries(expected));
  const right = JSON.stringify(sortedEntries(actual));
  if (left !== right) {
    throw new Error(`${label} does not match package.json`);
  }
}

export function validateGeneratedLockfile({ path, content, packageJsonContent = null }) {
  const name = basename(path);

  if (name === "package-lock.json") {
    const lock = JSON.parse(content);
    if (!Number.isInteger(lock.lockfileVersion) || lock.lockfileVersion < 2) {
      throw new Error(`unsupported package-lock version in ${path}`);
    }
    const root = lock.packages?.[""];
    if (!root || typeof root !== "object") {
      throw new Error(`package-lock root package metadata missing in ${path}`);
    }

    if (packageJsonContent !== null) {
      const pkg = JSON.parse(packageJsonContent);
      for (const field of ["name", "version"]) {
        if (pkg[field] !== undefined && root[field] !== pkg[field]) {
          throw new Error(`package-lock root ${field} does not match package.json`);
        }
      }
      assertSameObject("package-lock dependencies", pkg.dependencies, root.dependencies);
      assertSameObject("package-lock devDependencies", pkg.devDependencies, root.devDependencies);
    }

    return {
      kind: "npm",
      lockfile_version: lock.lockfileVersion,
      package_count: Object.keys(lock.packages).length,
    };
  }

  if (name === "Cargo.lock") {
    if (!content.startsWith("# This file is automatically @generated by Cargo.")) {
      throw new Error(`Cargo.lock generated-file header missing in ${path}`);
    }
    const versionMatch = content.match(/^version = (\d+)$/m);
    if (!versionMatch) {
      throw new Error(`Cargo.lock format version missing in ${path}`);
    }

    const blocks = content.match(/\[\[package\]\][\s\S]*?(?=\n\[\[package\]\]|$)/g) ?? [];
    if (blocks.length === 0) {
      throw new Error(`Cargo.lock contains no package entries in ${path}`);
    }

    for (const block of blocks) {
      if (!/^name = ".+"$/m.test(block) || !/^version = ".+"$/m.test(block)) {
        throw new Error(`Cargo.lock package entry missing name or version in ${path}`);
      }
      if (/^source = "registry\+/m.test(block) && !/^checksum = "[0-9a-f]{64}"$/m.test(block)) {
        throw new Error(`Cargo.lock registry package missing checksum in ${path}`);
      }
    }

    return {
      kind: "cargo",
      lockfile_version: Number(versionMatch[1]),
      package_count: blocks.length,
    };
  }

  throw new Error(`unsupported generated lockfile: ${path}`);
}
